<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php'; require_login();
require_once __DIR__.'/../config/database.php'; verify_csrf();
$mensaje='';$error='';$programas=['Arquitectura de Plataformas y Servicios de TI','Enfermería Técnica','Contabilidad','Producción Agropecuaria'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_role(['administrador','tesorero']);
 $dni=trim($_POST['dni']??'');$nombre=trim($_POST['nombres']??'');$direccion=trim($_POST['direccion']??'');$programa=$_POST['programa_estudio']??'';
 $desc=trim($_POST['descripcion']??'');$monto=filter_var($_POST['monto']??null,FILTER_VALIDATE_FLOAT);$medio=$_POST['medio_pago']??'Efectivo';
 if(!preg_match('/^\d{8}$/',$dni)||$nombre===''||!in_array($programa,$programas,true)||$desc===''||$monto===false||$monto<=0||!in_array($medio,['Efectivo','Transferencia','Tarjeta','Depósito','Yape/Plin'],true))$error='Completa los datos correctamente. El DNI debe tener 8 dígitos y el monto debe ser mayor a cero.';
 else{
  try{$pdo->beginTransaction();
   $q=$pdo->prepare('INSERT INTO estudiantes(dni,nombres,direccion,programa_estudio) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE nombres=VALUES(nombres),direccion=VALUES(direccion),programa_estudio=VALUES(programa_estudio)');
   $q->execute([$dni,$nombre,$direccion,$programa]);$q=$pdo->prepare('SELECT id FROM estudiantes WHERE dni=?');$q->execute([$dni]);$est=(int)$q->fetchColumn();
   $q=$pdo->prepare("INSERT INTO movimientos(tipo,fecha,concepto,referencia,monto,estado,usuario_id,confirmado_por,confirmado_en) VALUES('INGRESO',CURDATE(),?,?,?,'CONFIRMADO',?,?,NOW())");
   $ref='RECIBO DE CAJA';$q->execute([$desc,$ref,$monto,$_SESSION['usuario']['id'],$_SESSION['usuario']['id']]);$mov=(int)$pdo->lastInsertId();
   $temporal='TMP-'.bin2hex(random_bytes(8));
   $q=$pdo->prepare('INSERT INTO recibos(numero,estudiante_id,movimiento_id,descripcion,cantidad,precio_unitario,total,medio_pago,emitido_por) VALUES(?,?,?, ?,1,?,?,?,?)');
   $q->execute([$temporal,$est,$mov,$desc,$monto,$monto,$medio,$_SESSION['usuario']['id']]);$rid=(int)$pdo->lastInsertId();
   $numero='002-'.str_pad((string)(20381+$rid),7,'0',STR_PAD_LEFT);
   $q=$pdo->prepare('UPDATE recibos SET numero=? WHERE id=?');$q->execute([$numero,$rid]);
   audit($pdo,'EMITIR_RECIBO','recibos',$rid,'Recibo '.$numero.' · S/ '.number_format((float)$monto,2,'.',''));
   $pdo->commit();header('Location: recibos.php?id='.$rid);exit;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='No se pudo emitir el recibo. Verifica que la migración SQL esté instalada.';}
 }
}
$id=(int)($_GET['id']??0);$rec=null;
if($id){$q=$pdo->prepare('SELECT r.*,e.dni,e.nombres,e.direccion,e.programa_estudio,u.nombre usuario FROM recibos r JOIN estudiantes e ON e.id=r.estudiante_id JOIN usuarios u ON u.id=r.emitido_por WHERE r.id=?');$q->execute([$id]);$rec=$q->fetch();if(!$rec){http_response_code(404);exit('Recibo no encontrado.');}}
$recent=$pdo->query('SELECT r.id,r.numero,r.fecha_emision,r.total,e.nombres,e.dni FROM recibos r JOIN estudiantes e ON e.id=r.estudiante_id ORDER BY r.id DESC LIMIT 15')->fetchAll();
?>
